//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: cdc_open_loop
// Purpose: Open-loop multi-bit CDC using valid/data stretching.
//
// The source asserts src_valid for one cycle. The module captures the data
// and stretches the valid signal for STRETCH_CYCLES source clock cycles,
// holding data stable throughout. A multi-stage synchronizer in the
// destination domain samples the stretched valid and latches the data on
// the rising edge.
//
// The source data bus must remain stable long enough for the
// synchronized enable to propagate through the destination sync
// chain and load the destination register. That gives:
//
//   STRETCH_CYCLES >= ceil((SYNC_STAGES + 1) * T_dst / T_src)
//
// where T_dst and T_src are the destination and source clock
// periods. (SYNC_STAGES + 1) counts the sync FFs plus the load edge.
// Example: a 1 GHz source crossing to 100 MHz with SYNC_STAGES=2
// needs STRETCH_CYCLES >= ceil(3 * 10/1) = 30. The 1.5*T_dst rule of
// thumb is enough to capture the valid pulse alone, but the multi-bit
// data bus needs the longer hold so r_src_data is still stable when
// the destination latches it.
//
// This is a true open-loop design: no return path, no handshake, no
// backpressure. The source is busy for exactly STRETCH_CYCLES and then
// free to send again. If the destination misses the stretched valid
// (because STRETCH_CYCLES is too short), the transfer is silently lost.
//
// Use when:
//   - Clock ratio is known and fixed (or bounded)
//   - Destination is always ready (no flow control needed)
//   - Minimum area/complexity is desired
//   - Config registers, status updates, infrequent events
//
// For unknown/variable clock ratios, use cdc_2_phase_handshake (closed-loop).
// For streaming data, use fifo_async or gaxi_fifo_async.
//
// Documentation: docs/markdown/rtl-cdc/cdc.md#cdc_open_loop
// Subsystem: cdc
//
// Author: sean galloway
// Created: 2026-04-21
//
// ===========================================================================
// REQUIRED SDC CONSTRAINTS
// ---------------------------------------------------------------------------
//   # 1. Stretched valid (single-bit, synchronized by destination)
//   set_max_delay -datapath_only \
//       -from [get_pins u_cdc/r_src_valid_stretch_reg/C] \
//       -to   [get_pins u_cdc/u_valid_sync/q_reg[0]/D] \
//       <dst_period_ns>
//
//   # 2. Data bus (quasi-static, held for STRETCH_CYCLES src clocks)
//   set_max_delay -datapath_only \
//       -from [get_pins u_cdc/r_src_data_reg[*]/C] \
//       -to   [get_pins u_cdc/r_dst_data_reg[*]/D] \
//       <dst_period_ns>
//
// ===========================================================================

`timescale 1ns / 1ps

`include "reset_defs.svh"

module cdc_open_loop #(
    parameter int DATA_WIDTH     = 8,    // Width of the data bus
    parameter int STRETCH_CYCLES = 8,    // Source clocks to hold valid+data (manual default)
    parameter int SYNC_STAGES    = 2,    // Destination synchronizer depth (2-4)

    // ---- Auto-compute STRETCH_CYCLES from clock periods (opt-in) ----
    //
    // The destination needs at least (SYNC_STAGES + 1) dst-clock periods
    // to safely capture a stretched pulse. Required hold time:
    //
    //     STRETCH * src_period >= (SYNC_STAGES + 1) * dst_period
    //
    // Solved for STRETCH:
    //
    //     STRETCH = ceil((SYNC_STAGES + 1) * SRC_CLK_HZ / DST_CLK_HZ)
    //
    // To turn this on, set AUTO_STRETCH = 1 and provide SRC_CLK_HZ (the
    // FASTEST source clock you want handled safely; sources above this
    // start dropping pulses) and DST_CLK_HZ. When AUTO_STRETCH = 0
    // (default), the STRETCH_CYCLES parameter above is used verbatim —
    // no breaking change for existing callers.
    parameter int AUTO_STRETCH = 0,   // 0 = use STRETCH_CYCLES; 1 = auto-compute
    parameter int SRC_CLK_HZ   = 25_000_000,
    parameter int DST_CLK_HZ   = 100_000_000
) (
    // Source clock domain
    input  logic                  clk_src,      // Source domain clock
    input  logic                  rst_src_n,    // Source domain async reset (active low)
    input  logic                  src_valid,    // Single-cycle pulse: data is valid NOW
    input  logic [DATA_WIDTH-1:0] src_data,     // Data from source domain
    output logic                  src_busy,     // High during stretch (blocks next valid)

    // Destination clock domain
    input  logic                  clk_dst,      // Destination domain clock
    input  logic                  rst_dst_n,    // Destination domain async reset (active low)
    output logic                  dst_valid,    // Single-cycle pulse: data latched
    output logic [DATA_WIDTH-1:0] dst_data      // Latched data (stable until next dst_valid)
);

    // Auto-compute (elaboration time; folds to a literal in synth).
    localparam int STRETCH_AUTO_VAL =
        ((SYNC_STAGES + 1) * SRC_CLK_HZ + DST_CLK_HZ - 1) / DST_CLK_HZ;
    localparam int STRETCH_RAW   = (AUTO_STRETCH != 0) ? STRETCH_AUTO_VAL : STRETCH_CYCLES;
    // Clamp >= 1: STRETCH=0 would assert valid for zero cycles.
    localparam int STRETCH_EFF   = (STRETCH_RAW > 0) ? STRETCH_RAW : 1;

    // Counter width to hold the effective STRETCH.
    localparam int CTR_WIDTH = $clog2(STRETCH_EFF + 1);

    //=========================================================================
    // Source domain: capture data and stretch valid
    //=========================================================================
    // On src_valid (when not busy), capture data and assert r_src_valid_stretch
    // for STRETCH_CYCLES. Both data and stretched valid cross to the destination
    // as quasi-static signals.

    logic [DATA_WIDTH-1:0] r_src_data;
    logic                  r_src_valid_stretch;
    logic [CTR_WIDTH-1:0]  r_stretch_count;

    assign src_busy = (r_stretch_count != '0);

    `ALWAYS_FF_RST(clk_src, rst_src_n,
        if (`RST_ASSERTED(rst_src_n)) begin
            r_src_data          <= '0;
            r_src_valid_stretch <= 1'b0;
            r_stretch_count     <= '0;
        end else begin
            if (src_valid && !src_busy) begin
                // New transfer: capture data, start stretching
                r_src_data          <= src_data;
                r_src_valid_stretch <= 1'b1;
                r_stretch_count     <= CTR_WIDTH'(STRETCH_EFF);
            end else if (r_stretch_count != '0) begin
                // Counting down
                r_stretch_count <= r_stretch_count - 1'b1;
                if (r_stretch_count == CTR_WIDTH'(1)) begin
                    // Last cycle -- deassert stretched valid
                    r_src_valid_stretch <= 1'b0;
                end
            end
        end
    )

    //=========================================================================
    // Destination domain: synchronize stretched valid, edge-detect, latch data
    //=========================================================================
    // The stretched valid is a level signal held for many source clocks.
    // The multi-stage synchronizer resolves metastability. We detect the
    // rising edge of the synchronized valid and latch data on that edge.

    logic w_valid_sync;

    glitch_free_n_dff_arn #(
        .FLOP_COUNT (SYNC_STAGES),
        .WIDTH      (1)
    ) u_valid_sync (
        .clk   (clk_dst),
        .rst_n (rst_dst_n),
        .d     (r_src_valid_stretch),
        .q     (w_valid_sync)
    );

    // Rising edge detect on synchronized valid
    logic r_valid_sync_prev;

    wire w_valid_rise = w_valid_sync && !r_valid_sync_prev;

    `ALWAYS_FF_RST(clk_dst, rst_dst_n,
        if (`RST_ASSERTED(rst_dst_n)) begin
            r_valid_sync_prev <= 1'b0;
            dst_data          <= '0;
            dst_valid         <= 1'b0;
        end else begin
            r_valid_sync_prev <= w_valid_sync;
            dst_valid         <= w_valid_rise;
            if (w_valid_rise) begin
                dst_data <= r_src_data;
            end
        end
    )

endmodule : cdc_open_loop

// cdc_pulse.sv — Pulse Synchronizer
// Two modes selectable via MODE parameter:
//   MODE=0 (TOGGLE): Toggle-based — i_src_pulse toggles a FF, level crosses via
//                     cdc_bit, edge detect in dst produces single-cycle pulse.
//                     Lightweight, but back-to-back pulses must be spaced apart.
//   MODE=1 (COUNTER): Counter-based — delegates to cdc_counter which owns the
//                      pulse count in the src domain and synchronizes it to dst.
//                      dst generates pulses to match. Guarantees N-in = N-out.

`include "cdc_config.svh"

module cdc_pulse_toggle #(
    parameter int SYNC_STAGES = 2
) (
    input  logic i_src_clk,
    input  logic i_src_rst_n,
    input  logic i_src_pulse,
    input  logic i_dst_clk,
    input  logic i_dst_rst_n,
    output logic o_dst_pulse
);

    logic toggle_src;
    logic toggle_dst;
    logic toggle_dst_prev;

    `ifndef CDC_ASYNC_RESET
    initial begin
        toggle_src      = 1'b0;
        toggle_dst_prev = 1'b0;
    end
    `endif

    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_src_clk or negedge i_src_rst_n) begin
    `else
    always_ff @(posedge i_src_clk) begin
    `endif
        if (!i_src_rst_n)
            toggle_src <= 1'b0;
        else if (i_src_pulse)
            toggle_src <= ~toggle_src;
    end

    cdc_bit #(
        .SYNC_STAGES (SYNC_STAGES),
        .RESET_VALUE (1'b0)
    ) u_sync_toggle (
        .i_clk      (i_dst_clk),
        .i_rst_n    (i_dst_rst_n),
        .i_async_in (toggle_src),
        .o_sync_out (toggle_dst)
    );

    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_dst_clk or negedge i_dst_rst_n) begin
    `else
    always_ff @(posedge i_dst_clk) begin
    `endif
        if (!i_dst_rst_n)
            toggle_dst_prev <= 1'b0;
        else
            toggle_dst_prev <= toggle_dst;
    end

    assign o_dst_pulse = toggle_dst ^ toggle_dst_prev;

endmodule


module cdc_pulse_counter #(
    parameter int SYNC_STAGES = 2,
    parameter int CTR_WIDTH   = 4
) (
    input  logic i_src_clk,
    input  logic i_src_rst_n,
    input  logic i_src_pulse,
    input  logic i_dst_clk,
    input  logic i_dst_rst_n,
    output logic o_dst_pulse
);

    logic [CTR_WIDTH-1:0] dst_count_sync;
    logic [CTR_WIDTH-1:0] dst_count_local;
    logic                 dst_pulse_r;

    `ifndef CDC_ASYNC_RESET
    initial begin
        dst_count_local = '0;
        dst_pulse_r     = 1'b0;
    end
    `endif

    // cdc_counter owns the src-domain pulse count and synchronizes it to dst.
    cdc_counter #(
        .WIDTH       (CTR_WIDTH),
        .SYNC_STAGES (SYNC_STAGES)
    ) u_sync_count (
        .i_src_clk    (i_src_clk),
        .i_src_rst_n  (i_src_rst_n),
        .i_count_up   (i_src_pulse),
        .i_count_down (1'b0),
        .o_src_count  (),
        .i_dst_clk    (i_dst_clk),
        .i_dst_rst_n  (i_dst_rst_n),
        .o_dst_gray   (),
        .o_dst_count  (dst_count_sync)
    );

    // Generate one pulse per count difference: exactly 1 dst_clk wide,
    // mandatory 1-cycle gap between consecutive pulses (self-gating via dst_pulse_r).
    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_dst_clk or negedge i_dst_rst_n) begin
    `else
    always_ff @(posedge i_dst_clk) begin
    `endif
        if (!i_dst_rst_n) begin
            dst_count_local <= '0;
            dst_pulse_r     <= 1'b0;
        end else begin
            dst_pulse_r <= 1'b0;
            if (!dst_pulse_r && (dst_count_local != dst_count_sync)) begin
                dst_pulse_r     <= 1'b1;
                dst_count_local <= dst_count_local + 1'b1;
            end
        end
    end

    assign o_dst_pulse = dst_pulse_r;

endmodule


// Top-level wrapper — instantiates one mode based on MODE parameter
module cdc_pulse #(
    parameter int SYNC_STAGES = 2,
    parameter int MODE        = 0,       // 0 = toggle, 1 = counter
    parameter int CTR_WIDTH   = 4        // Counter width for MODE=1
) (
    input  logic i_src_clk,
    input  logic i_src_rst_n,
    input  logic i_src_pulse,
    input  logic i_dst_clk,
    input  logic i_dst_rst_n,
    output logic o_dst_pulse
);

generate
    if (MODE == 0) begin : gen_toggle
        cdc_pulse_toggle #(
            .SYNC_STAGES (SYNC_STAGES)
        ) u_impl (
            .i_src_clk    (i_src_clk),
            .i_src_rst_n  (i_src_rst_n),
            .i_src_pulse  (i_src_pulse),
            .i_dst_clk    (i_dst_clk),
            .i_dst_rst_n  (i_dst_rst_n),
            .o_dst_pulse  (o_dst_pulse)
        );
    end else begin : gen_counter
        cdc_pulse_counter #(
            .SYNC_STAGES (SYNC_STAGES),
            .CTR_WIDTH   (CTR_WIDTH)
        ) u_impl (
            .i_src_clk    (i_src_clk),
            .i_src_rst_n  (i_src_rst_n),
            .i_src_pulse  (i_src_pulse),
            .i_dst_clk    (i_dst_clk),
            .i_dst_rst_n  (i_dst_rst_n),
            .o_dst_pulse  (o_dst_pulse)
        );
    end
endgenerate

endmodule

// =============================================================================
// Module  : cdc_pulse_sync
// Language: SystemVerilog
//
// Description:
//   Pulse synchronizer for crossing a single-cycle pulse from the source
//   clock domain to the destination clock domain.
//
// CDC Principle (Toggle-Based Pulse Synchronization):
//   A single-cycle pulse may be shorter than one destination clock period and
//   could be invisible to a simple synchronizer. This module uses a three-step
//   toggle-based approach:
//
//   Step 1 – Pulse-to-Toggle (source domain):
//     A flip-flop toggles on each input pulse, converting the short pulse to
//     a persistent level change that cannot be missed by the synchronizer.
//
//   Step 2 – 2-Stage Synchronization:
//     The toggle signal is synchronized to the destination domain using a
//     standard 2-stage flip-flop chain, eliminating metastability.
//
//   Step 3 – Toggle-to-Pulse (destination domain):
//     An XOR of the current and previous synchronized toggle detects each
//     toggle edge and regenerates a single-cycle pulse in the destination domain.
//
// Safety:
//   - Safe because only a persistent toggle (not the original pulse) crosses
//     the clock boundary.
//   - Pulses must be separated by at least the round-trip synchronization
//     latency: approximately 4 destination clock cycles (2 sync + 1 edge
//     detect + 1 margin) to prevent pulse merging.
//
// Use Cases:
//   - Crossing a single-cycle strobe or trigger between clock domains
//   - Interrupt signals between clock domains
//   - Event notification across clock domain boundaries
//
// Limitations:
//   - Minimum inter-pulse spacing: ~4 destination clock cycles; pulses closer
//     together may be lost.
//   - 2–3 destination clock cycles of latency.
//   - Does not detect pulse loss (no overflow flag).
//
// Timing Assumptions:
//   - One pulse in = one pulse out, assuming minimum spacing is met.
//   - Does not preserve data associated with the pulse (use cdc_data_sync for
//     data transfer).
//
// Example Instantiation:
//   cdc_pulse_sync u_pulse_sync (
//       .clk_src   (clk_src),
//       .rst_src_n (rst_src_n),
//       .pulse_src (strobe_src),
//       .clk_dst   (clk_dst),
//       .rst_dst_n (rst_dst_n),
//       .pulse_dst (strobe_dst)
//   );
// =============================================================================

module cdc_pulse_sync (
    // Source domain
    input  logic clk_src,    // Source domain clock
    input  logic rst_src_n,  // Source domain reset (active low)
    input  logic pulse_src,  // Single-cycle input pulse in source domain

    // Destination domain
    input  logic clk_dst,    // Destination domain clock
    input  logic rst_dst_n,  // Destination domain reset (active low)
    output logic pulse_dst   // Single-cycle output pulse in destination domain
);

    // --------------------------------------------------------------------------
    // Step 1: Convert pulse to toggle in the source domain.
    // The toggle persists between pulses so it cannot be missed.
    // --------------------------------------------------------------------------
    logic toggle_src;

    always_ff @(posedge clk_src or negedge rst_src_n) begin
        if (!rst_src_n)
            toggle_src <= 1'b0;
        else if (pulse_src)
            toggle_src <= ~toggle_src;
    end

    // --------------------------------------------------------------------------
    // Step 2: 2-stage synchronizer to move toggle into destination domain.
    // --------------------------------------------------------------------------
    (* ASYNC_REG = "TRUE" *) logic [1:0] sync_ff;

    // --------------------------------------------------------------------------
    // Step 3: Edge detection to regenerate a single-cycle pulse.
    // --------------------------------------------------------------------------
    logic toggle_dst_prev;

    always_ff @(posedge clk_dst or negedge rst_dst_n) begin
        if (!rst_dst_n) begin
            sync_ff          <= 2'b00;
            toggle_dst_prev  <= 1'b0;
        end else begin
            sync_ff          <= {sync_ff[0], toggle_src};
            toggle_dst_prev  <= sync_ff[1];
        end
    end

    // Pulse output: high for exactly one destination clock cycle per event.
    assign pulse_dst = sync_ff[1] ^ toggle_dst_prev;

endmodule

// cdc_qualifier.sv — Valid-Qualified Data Bus Synchronizer
// Synchronizes a level-held i_valid into the destination clock domain via
// cdc_bit, then uses the synchronized valid as a load-enable to capture
// i_data into a destination-domain register. Caller must hold both i_data
// and i_valid stable for at least SYNC_STAGES+1 i_clk cycles — long enough
// for the valid synchronizer to settle before data is sampled.
//
// o_data lags o_valid by one extra i_clk cycle: o_valid is itself a
// registered output of cdc_bit, so the load-enable it drives is only
// visible to this module's always_ff one cycle after o_valid appears to
// assert. Total latency from i_valid asserting to o_data updating is
// SYNC_STAGES+1 i_clk cycles.

`include "cdc_config.svh"

module cdc_qualifier #(
    parameter int unsigned WIDTH       = 8,
    parameter int unsigned SYNC_STAGES = 2
) (
    // Destination clock domain
    input  logic                i_clk,
    input  logic                i_rst_n,

    // Source domain — i_data must remain stable while i_valid is held high
    input  logic [WIDTH-1:0]    i_data,
    input  logic                i_valid,

    // Destination domain
    output logic [WIDTH-1:0]    o_data,
    output logic                o_valid
);

    // Level-held valid crosses the CDC boundary through the standard
    // single-bit synchronizer.
    cdc_bit #(
        .SYNC_STAGES (SYNC_STAGES),
        .RESET_VALUE (1'b0)
    ) u_sync_valid (
        .i_clk      (i_clk),
        .i_rst_n    (i_rst_n),
        .i_async_in (i_valid),
        .o_sync_out (o_valid)
    );

    `ifndef CDC_ASYNC_RESET
    initial begin
        o_data = '0;
    end
    `endif

    // Capture i_data directly while the synchronized valid is asserted.
    // Safe because i_data is required to be stable for the whole window
    // o_valid is high, not just at a single edge.
    `ifdef CDC_ASYNC_RESET
    always_ff @(posedge i_clk or negedge i_rst_n) begin
    `else
    always_ff @(posedge i_clk) begin
    `endif
        if (!i_rst_n) begin
            o_data <= '0;
        end else if (o_valid) begin
            o_data <= i_data;
        end
    end

endmodule

// cdc_reset.sv — Reset Synchronizer
// Async assert, synchronous deassert reset synchronizer.
// This is the one valid use of async reset in FPGA design.
// Active-low reset: i_async_rst_n=0 asserts instantly, deasserts after SYNC_STAGES clocks.

`include "cdc_config.svh"

module cdc_reset #(
    parameter int SYNC_STAGES = 2
) (
    input  logic i_clk,
    input  logic i_async_rst_n,    // Active-low async reset input
    output logic o_sync_rst_n      // Active-low synchronized reset output
);

    (* ASYNC_REG = "TRUE" *)
    logic [SYNC_STAGES-1:0] rst_chain;

    initial begin
        rst_chain = {SYNC_STAGES{1'b0}};  // Power-up in reset
    end

    // Async assert (immediate on rst_n=0), sync deassert (after SYNC_STAGES clocks)
    always_ff @(posedge i_clk or negedge i_async_rst_n) begin
        if (!i_async_rst_n)
            rst_chain <= {SYNC_STAGES{1'b0}};
        else
            rst_chain <= {rst_chain[SYNC_STAGES-2:0], 1'b1};
    end

    assign o_sync_rst_n = rst_chain[SYNC_STAGES-1];

endmodule

// =============================================================================
// Module  : cdc_reset_sync
// Language: SystemVerilog
//
// Description:
//   Reset synchronizer with asynchronous assertion and synchronous deassertion.
//   Generates a clean, glitch-free reset in a target clock domain from an
//   asynchronous reset source.
//
// CDC Principle (Async Assert / Sync Deassert):
//   This is a well-established technique for distributing resets across clock
//   domains safely:
//
//   Assertion (immediate):
//     When rst_async_n goes low, the output rst_sync_n is immediately driven
//     low (asynchronous), ensuring that all downstream flip-flops enter reset
//     without waiting for a clock edge. This prevents "reset race" conditions.
//
//   Deassertion (synchronized):
//     When rst_async_n goes high, the release is NOT immediate. Instead, it
//     must propagate through a chain of SYNC_STAGES flip-flops clocked by
//     clk. All flip-flops in the chain are preset to '1' asynchronously and
//     only release rst_sync_n after SYNC_STAGES clean clock edges, ensuring
//     the local reset deasserts synchronously with clk. This prevents
//     metastability on the reset release edge.
//
// Safety:
//   - Async assert ensures no combinatorial reset propagation delay.
//   - Sync deassert eliminates metastability when reset is released.
//   - All flip-flops driven by rst_sync_n will exit reset at the same clock edge.
//
// Use Cases:
//   - Generating domain-local resets from a global asynchronous reset source
//   - Power-on reset distribution to multiple clock domains
//   - Generating reset for logic after a PLL lock signal
//
// Limitations:
//   - Clock must be running during reset deassertion for synchronous release.
//   - SYNC_STAGES >= 2 is required (default 2).
//   - The metastability window is very small for the assertion path (since the
//     reset release goes through synchronizer FFs), but assertion itself is
//     asynchronous and purely combinatorial.
//
// Timing Assumptions:
//   - rst_async_n is assumed to meet hold/recovery time on the clock edge it
//     is released on. If not, the SYNC_STAGES chain provides sufficient
//     resolution time.
//
// Example Instantiation:
//   cdc_reset_sync #(.SYNC_STAGES(2)) u_rst_sync (
//       .clk         (clk),
//       .rst_async_n (por_rst_n),
//       .rst_sync_n  (local_rst_n)
//   );
// =============================================================================

module cdc_reset_sync #(
    parameter int SYNC_STAGES = 2  // Number of synchronizer stages (>= 2)
) (
    input  logic clk,          // Target clock domain clock
    input  logic rst_async_n,  // Asynchronous reset input (active low)
    output logic rst_sync_n    // Synchronized reset output (active low)
);

    // Synchronizer chain: all FFs are asynchronously cleared and preset to 1.
    // When rst_async_n goes low:  entire chain goes to 0 (async clear).
    // When rst_async_n goes high: chain shifts in 1s from the LSB.
    (* ASYNC_REG = "TRUE" *) logic [SYNC_STAGES-1:0] sync_chain;

    always_ff @(posedge clk or negedge rst_async_n) begin
        if (!rst_async_n)
            // Asynchronous assertion: immediately drive all stages to 0
            sync_chain <= '0;
        else
            // Synchronous deassertion: shift a 1 from LSB toward MSB
            sync_chain <= {sync_chain[SYNC_STAGES-2:0], 1'b1};
    end

    // Reset output is active until the chain is fully loaded with 1s
    assign rst_sync_n = sync_chain[SYNC_STAGES-1];

endmodule

// =============================================================================
// Module  : cdc_sync2
// Language: SystemVerilog
//
// Description:
//   2-stage flip-flop synchronizer for single-bit clock domain crossing (CDC).
//
// CDC Principle:
//   When a signal crosses clock domains, the capturing flip-flop may enter a
//   metastable state. By chaining two flip-flops in the destination domain,
//   the probability that metastability propagates to downstream logic is reduced
//   exponentially (by roughly e^(Tresolution/tau) per stage). For most designs
//   below a few hundred MHz, 2 stages provide sufficient MTBF.
//
// Safety:
//   - Safe ONLY for single-bit signals.
//   - The input must be quasi-static (stable for at least one destination clock
//     cycle) or use cdc_pulse_sync / cdc_toggle_sync for pulsed signals.
//   - Multi-bit signals require special handling (Gray code or handshake).
//   - Apply ASYNC_REG / keep_hierarchy constraints in the synthesis tool to
//     prevent the optimizer from merging or moving synchronizer FFs.
//
// Use Cases:
//   - Control/status bits crossing clock domains
//   - Enable, valid, or flag signals
//   - Building block for cdc_pulse_sync, cdc_toggle_sync, cdc_reset_sync
//
// Limitations:
//   - 2-cycle latency in the destination domain
//   - Not suitable for fast-changing signals or multi-bit buses
//
// Timing Assumptions:
//   - The signal must remain stable for at least 2 destination clock cycles
//     between transitions (quasi-static) unless a toggle/pulse synchronizer
//     is used upstream.
//
// Example Instantiation:
//   cdc_sync2 #(.RESET_VAL(1'b0)) u_sync (
//       .clk_dst   (clk_dst),
//       .rst_dst_n (rst_dst_n),
//       .data_src  (flag_src),
//       .data_dst  (flag_dst)
//   );
// =============================================================================

module cdc_sync2 #(
    parameter bit RESET_VAL = 1'b0  // Reset value for synchronizer flip-flops
) (
    input  logic clk_dst,    // Destination domain clock
    input  logic rst_dst_n,  // Destination domain asynchronous reset (active low)
    input  logic data_src,   // Single-bit input from source clock domain
    output logic data_dst    // Single-bit output synchronized to destination domain
);

    // Two-stage synchronizer chain.
    // ASYNC_REG attribute prevents optimization across flip-flop stages and
    // guides place-and-route tools to co-locate the FFs for minimal routing
    // delay, reducing the probability of metastability propagation.
    (* ASYNC_REG = "TRUE" *) logic [1:0] sync_ff;

    always_ff @(posedge clk_dst or negedge rst_dst_n) begin
        if (!rst_dst_n)
            sync_ff <= {2{RESET_VAL}};
        else
            sync_ff <= {sync_ff[0], data_src};
    end

    assign data_dst = sync_ff[1];

endmodule

// =============================================================================
// Module  : cdc_sync3
// Language: SystemVerilog
//
// Description:
//   3-stage flip-flop synchronizer for single-bit CDC. Provides higher MTBF
//   than the 2-stage synchronizer.
//
// CDC Principle:
//   Same principle as cdc_sync2 but with a third synchronizer flip-flop.
//   Each additional stage reduces the metastability probability by roughly
//   e^(Tresolution/tau) relative to the previous stage. Use 3 stages when:
//     - Operating at high clock frequencies (>500 MHz), where the destination
//       clock period may not allow sufficient metastability resolution time
//       between the first and second FF.
//     - The application demands very high MTBF (e.g., safety-critical systems).
//
// Safety:
//   - Safe ONLY for single-bit signals.
//   - Same input stability requirements as cdc_sync2.
//   - Apply ASYNC_REG / keep_hierarchy constraints in synthesis tools.
//
// Use Cases:
//   - High-frequency designs (>500 MHz)
//   - Safety-critical applications requiring very high MTBF
//   - When 2-stage does not provide enough resolution time at the target frequency
//
// Limitations:
//   - 3-cycle latency in the destination domain (one more cycle than cdc_sync2)
//   - Not suitable for fast-changing or multi-bit signals
//
// Timing Assumptions:
//   - Destination clock period must be long enough for the first FF to resolve
//     metastability before its output is sampled by the second FF.
//
// Example Instantiation:
//   cdc_sync3 #(.RESET_VAL(1'b0)) u_sync3 (
//       .clk_dst   (clk_dst),
//       .rst_dst_n (rst_dst_n),
//       .data_src  (flag_src),
//       .data_dst  (flag_dst)
//   );
// =============================================================================

module cdc_sync3 #(
    parameter bit RESET_VAL = 1'b0  // Reset value for synchronizer flip-flops
) (
    input  logic clk_dst,    // Destination domain clock
    input  logic rst_dst_n,  // Destination domain asynchronous reset (active low)
    input  logic data_src,   // Single-bit input from source clock domain
    output logic data_dst    // Single-bit output synchronized to destination domain
);

    // Three-stage synchronizer chain.
    // ASYNC_REG attribute prevents optimization across stages and guides
    // place-and-route to co-locate the FFs for minimum routing delay.
    (* ASYNC_REG = "TRUE" *) logic [2:0] sync_ff;

    always_ff @(posedge clk_dst or negedge rst_dst_n) begin
        if (!rst_dst_n)
            sync_ff <= {3{RESET_VAL}};
        else
            sync_ff <= {sync_ff[1:0], data_src};
    end

    assign data_dst = sync_ff[2];

endmodule

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2024-2025 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: cdc_synchronizer
// Purpose: Multi-bit synchronizer for clock domain crossing
//
// This module provides a simple CDC synchronizer interface that wraps
// the glitch_free_n_dff_arn module for consistent naming across the
// AMBA infrastructure.
//
// Documentation: docs/markdown/rtl-cdc/cdc.md#cdc_synchronizer
// Subsystem: cdc
//
// Author: sean galloway
// Created: 2025-12-23

`timescale 1ns / 1ps

module cdc_synchronizer #(
    parameter int WIDTH      = 1,   // Bus width to synchronize
    parameter int FLOP_COUNT = 3    // Number of synchronizer stages (2-5)
) (
    input  logic             clk,       // Destination clock
    input  logic             rst_n,     // Asynchronous active-low reset
    input  logic [WIDTH-1:0] async_in,  // Asynchronous input from source domain
    output logic [WIDTH-1:0] sync_out   // Synchronized output in destination domain
);

    // Use the glitch_free_n_dff_arn module for the actual synchronization
    glitch_free_n_dff_arn #(
        .FLOP_COUNT (FLOP_COUNT),
        .WIDTH      (WIDTH)
    ) u_sync (
        .clk   (clk),
        .rst_n (rst_n),
        .d     (async_in),
        .q     (sync_out)
    );

endmodule : cdc_synchronizer

// =============================================================================
// Module  : cdc_toggle_sync
// Language: SystemVerilog
//
// Description:
//   Toggle-event synchronizer. Synchronizes a toggle signal from the source
//   clock domain to the destination domain and generates a single-cycle pulse
//   on each toggle edge.
//
// CDC Principle:
//   Instead of sending a short pulse (which might be missed if shorter than
//   one destination clock period), the source toggles a persistent signal each
//   time an event occurs. The toggle is synchronized with a 2-stage FF chain.
//   An XOR of the synchronized toggle with its previous value detects each
//   edge and generates a single-cycle output pulse in the destination domain.
//
// Safety:
//   - Safe for CDC because the toggle is persistent (does not need to be
//     captured within a specific clock window).
//   - The 2FF chain handles metastability on the toggle crossing.
//   - Events must be separated by at least 3 destination clock cycles for
//     reliable detection (2 sync cycles + 1 cycle for edge detection).
//
// Use Cases:
//   - Signaling infrequent events across clock domains
//   - When the source already provides a toggle signal
//   - Building block for cdc_pulse_sync (which adds the src toggle generation)
//
// Limitations:
//   - Consecutive events must be separated by >= 3 destination clock cycles.
//   - Back-to-back high-frequency events may be missed if spacing is too short.
//
// Timing Assumptions:
//   - toggle_src must be stable for at least one destination clock cycle before
//     each new transition.
//
// Example Instantiation:
//   cdc_toggle_sync u_tog_sync (
//       .clk_dst    (clk_dst),
//       .rst_dst_n  (rst_dst_n),
//       .toggle_src (my_toggle),
//       .toggle_dst (toggle_synced),
//       .pulse_dst  (event_pulse)
//   );
// =============================================================================

module cdc_toggle_sync (
    // Destination domain
    input  logic clk_dst,     // Destination domain clock
    input  logic rst_dst_n,   // Destination domain reset (active low)
    // Cross-domain input
    input  logic toggle_src,  // Toggle signal from source clock domain
    // Destination domain outputs
    output logic toggle_dst,  // Synchronized toggle in destination domain
    output logic pulse_dst    // One-cycle pulse on each toggle transition
);

    // Two-stage synchronizer for the toggle signal.
    (* ASYNC_REG = "TRUE" *) logic [1:0] sync_ff;

    // Previous value of synchronized toggle (for edge detection).
    logic toggle_dst_prev;

    always_ff @(posedge clk_dst or negedge rst_dst_n) begin
        if (!rst_dst_n) begin
            sync_ff          <= 2'b00;
            toggle_dst_prev  <= 1'b0;
        end else begin
            sync_ff          <= {sync_ff[0], toggle_src};
            toggle_dst_prev  <= sync_ff[1];
        end
    end

    // Synchronized toggle output
    assign toggle_dst = sync_ff[1];

    // Single-cycle pulse on any toggle edge (rising or falling)
    assign pulse_dst = sync_ff[1] ^ toggle_dst_prev;

endmodule

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: chi_link_rx
// Purpose: RXLINKACTIVEACK controller for the receive direction of a CHI
//          port: one LINKACTIVE pair covers every RX channel (B14.5)
//
// Documentation: docs/markdown/rtl-amba/chi/README.md
// Subsystem: amba
//
// The state is the {RXLINKACTIVEREQ, RXLINKACTIVEACK} pair (Table B14.1).
// RXLINKACTIVEREQ comes from the other component; it crosses through
// glitch_free_n_dff_arn (LINKACTIVE_SYNC_STAGES flops) and 0 stages is
// allowed for a known-synchronous system.
//
//   - ACTIVATE -> RUN: raise ACK when REQ is seen and cfg_rx_enable is set.
//     Credits are granted only in RUN (o_grant_ok); the receiver "must
//     assert LINKACTIVEACK and move to the RUN state before sending credits"
//     (Table B14.2).
//   - DEACTIVATE -> STOP: stop granting once the synchronized REQ is seen
//     low (o_grant_ok low); because of the synchronizer and the registered
//     LCRDV in chi_rx_channel, up to LINKACTIVE_SYNC_STAGES + 1 grants can
//     still leave after the pin fell. Table B14.2 permits that ("the
//     Receiver is permitted, but not required, to send credits when first
//     entering this state"; B14.5.1.1: it "could take some time to react");
//     the transmitter returns them. Flits still in flight are accepted by
//     the channels; ACK drops only when every channel reports its credits
//     home (i_all_returned), so the transmitter never sees ACK low while
//     it holds a credit.
//
// B14.6.3.4 ordering with this port's TX direction: RXACK rises only after
// TXREQ has risen (i_tx_req high) and falls only after TXREQ has fallen
// (i_tx_req low). chi_link_tx raises TXREQ when this direction leaves
// STOP, so a remote activation completes without the Protocol layer
// doing anything.
//
// cfg_rx_enable gates the activation only: once in RUN, credits flow until
// the link deactivates (a receiver must grant "in a timely manner" while
// the link is active, B14.2.1.1). The port top gives the same input to
// chi_link_tx, which will not start a handshake this side cannot finish.
//
// LINKACTIVE_SYNC_STAGES is 0 (known-synchronous system) or >= 2; the port
// top rejects 1 at elaboration. TXLINKACTIVEACK is sampled once in
// chi_link_tx: the pair is synchronous to CLK unless a clock-domain
// crossing bridge sits between the components (B14.7.1 says the same of
// SACTIVE), and that bridge, not this block, owns the synchronization.
//
// With LINK_CTRL = 0 credits are granted whenever cfg_rx_enable is set and
// ACK is tied low.
//
// Author: sean galloway
// Created: 2026-10-30

`timescale 1ns / 1ps

`include "reset_defs.svh"

module chi_link_rx
    import chi_pkg::*;
#(
    parameter bit LINK_CTRL             = 1'b1,
    parameter int LINKACTIVE_SYNC_STAGES = 2
) (
    input  logic       aclk,
    input  logic       aresetn,

    // Configuration
    input  logic       cfg_rx_enable,     // 0 = never acknowledge an activation (so never RUN)

    // From the channels and the transmit direction
    input  logic       i_all_returned,    // every RX channel has its credits home
    input  logic       i_tx_req,          // TXLINKACTIVEREQ this port drives

    // LINKACTIVE pair
    input  logic       i_req,             // RXLINKACTIVEREQ
    output logic       o_ack,             // RXLINKACTIVEACK

    // Direction state for the channels
    output logic       o_req_s,           // REQ in this clock domain (for chi_link_tx)
    output logic       o_grant_ok,        // channels may grant credits (RUN)
    output logic [1:0] o_state            // {REQ sampled, ACK}
);

    logic w_req_s;
    logic w_ack;

    if (LINK_CTRL) begin : g_link
        logic r_ack;

        if (LINKACTIVE_SYNC_STAGES >= 2) begin : g_sync
            glitch_free_n_dff_arn #(
                .FLOP_COUNT (LINKACTIVE_SYNC_STAGES),
                .WIDTH      (1)
            ) u_req_sync (
                .clk   (aclk),
                .rst_n (aresetn),
                .d     (i_req),
                .q     (w_req_s)
            );
        end else begin : g_nosync
            assign w_req_s = i_req;
        end

        `ALWAYS_FF_RST(aclk, aresetn,
            if (`RST_ASSERTED(aresetn)) begin
                r_ack <= 1'b0;
            end else begin
                if (w_req_s && !r_ack && cfg_rx_enable && i_tx_req)
                    r_ack <= 1'b1;                                   // ACTIVATE -> RUN
                else if (!w_req_s && r_ack && i_all_returned && !i_tx_req)
                    r_ack <= 1'b0;                                   // DEACTIVATE -> STOP
            end
        )

        assign w_ack      = r_ack;
        assign o_grant_ok = w_req_s && r_ack;
    end else begin : g_no_link
        assign w_req_s    = 1'b0;
        assign w_ack      = 1'b0;
        assign o_grant_ok = cfg_rx_enable;

        /* verilator lint_off UNUSEDSIGNAL */
        logic unused_link;
        assign unused_link = ^{aclk, aresetn, i_req, i_all_returned, i_tx_req};
        /* verilator lint_on UNUSEDSIGNAL */
    end

    assign o_ack   = w_ack;
    assign o_req_s = w_req_s;
    // Without link control the direction IS in RUN; the pins stay low but the
    // status says what the channels see
    assign o_state = LINK_CTRL ? {w_req_s, w_ack} : CHI_LINK_RUN;

endmodule : chi_link_rx

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 sean galloway
//
// RTL Design Sherpa - Industry-Standard RTL Design and Verification
// https://github.com/sean-galloway/RTLDesignSherpa
//
// Module: cxs_slave_cg
// Purpose: cxs_slave behind one amba_clock_gate_ctrl
//
// Documentation: docs/markdown/rtl-amba/cxs/cxs_slave_cg.md
// Subsystem: amba
//
// IHI 0079D 5.5 anticipates exactly this block: "It is common for the clock
// in the Receiver to stop during the STOP state ... The assertion of the
// CXSACTIVEREQ signal might be used to restart that clock."
//
// The core's `busy` covers every state in which a flit or a credit return
// can still arrive -- ACTIVEACK or the synchronized ACTIVEREQ high, or any
// credit outstanding -- plus a flit waiting on the FUB side. So the block
// gates only in STOP with every credit home and the FIFO empty, where the
// transmitter "must not send flits or credit returns" (5.2).
//
//   - CXS_LINK_CTRL = 1: gates in STOP; a rising CXSACTIVEREQ wakes it.
//   - CXS_LINK_CTRL = 0: credits stay outstanding indefinitely, `busy`
//     never falls, and this wrapper never gates (see cxs_master_cg).
//
// Activity terms (vault/handbook/design/clock-gating-activity-terms):
//   user_valid = core busy                       (includes fub_cxs_valid,
//                                                 the pending output)
//   axi_valid  = s_cxs_valid | s_cxs_crdrtn | ACTIVEREQ synchronized here
// CXSACTIVEREQ is asynchronous (5.5), so the wake term goes through its own
// glitch_free_n_dff_arn on the FREE-RUNNING aclk: a wake term must be in the
// gate's own clock domain, and the core's synchronizer sits on the gated
// clock and is frozen in STOP. Event outputs (CXSCRDGNT and its check bit,
// fub_cxs_valid) are masked with !cg_gating.
//
// Author: sean galloway
// Created: 2026-10-15

`timescale 1ns / 1ps

module cxs_slave_cg
    import cxs_pkg::*;
#(
    parameter int CXS_ISSUE             = CXS_ISSUE_D,
    parameter int CXS_DATA_WIDTH        = 256,
    parameter int CXS_MAX_PKT_PER_FLIT  = 2,
    parameter int CXS_START_ALIGN       = 16,
    parameter bit CXS_HAS_LAST          = 1'b0,
    parameter bit CXS_HAS_PRCLTYPE      = 1'b0,
    parameter int CXS_SRCID_WIDTH       = 0,
    parameter int CXS_TGTID_WIDTH       = 0,
    parameter int CXS_USER_WIDTH        = 0,
    parameter int CXS_MAX_CREDIT        = 15,
    parameter bit  CXS_CREDIT_BEYOND_SPEC = 1'b0,   // see cxs_master / cxs_slave
    parameter int  CXS_STREAM_PRCL_BITS   = 0,      // per-stream tracking key (cxs_stream_key)
    parameter int  CXS_STREAM_SRCID_BITS  = 0,
    parameter int  CXS_STREAM_TGTID_BITS  = 0,
    parameter bit CXS_LINK_CTRL         = 1'b1,
    parameter bit CXS_CHECK             = 1'b0,
    parameter int RX_FIFO_DEPTH         = CXS_MAX_CREDIT,
    parameter int ACTIVEREQ_SYNC_STAGES = 2,

    // Clock gating parameters
    parameter int CG_IDLE_COUNT_WIDTH   = 4,

    // Short and calculated params
    parameter int DW        = CXS_DATA_WIDTH,
    parameter int N         = CXS_MAX_PKT_PER_FLIT,
    parameter int CNTL_W    = cntl_width(N, DW, CXS_START_ALIGN),
    parameter int CNTL_PW   = port_w(CNTL_W),
    parameter int SRCID_PW  = port_w(CXS_SRCID_WIDTH),
    parameter int TGTID_PW  = port_w(CXS_TGTID_WIDTH),
    parameter int USER_PW   = port_w(CXS_USER_WIDTH),
    parameter int DATACHK_W = chk_width(DW),
    parameter int CNTLCHK_W = port_w(chk_width(CNTL_W)),
    parameter int USERCHK_W = port_w(chk_width(CXS_USER_WIDTH)),
    parameter int CRW       = $clog2(CXS_MAX_CREDIT + 1)
) (
    input  logic                           aclk,
    input  logic                           aresetn,

    // Clock gating configuration
    input  logic                           cfg_cg_enable,
    input  logic [CG_IDLE_COUNT_WIDTH-1:0] cfg_cg_idle_count,

    // Configuration
    input  logic                  cfg_rx_enable,
    input  logic                  cfg_deact_hint,

    // CXS Receiver interface
    input  logic                  s_cxs_valid,
    input  logic [DW-1:0]         s_cxs_data,
    input  logic [CNTL_PW-1:0]    s_cxs_cntl,
    input  logic                  s_cxs_last,
    input  logic [2:0]            s_cxs_prcltype,
    input  logic [SRCID_PW-1:0]   s_cxs_srcid,
    input  logic [TGTID_PW-1:0]   s_cxs_tgtid,
    input  logic [USER_PW-1:0]    s_cxs_user,
    output logic                  s_cxs_crdgnt,
    input  logic                  s_cxs_crdrtn,
    input  logic                  s_cxs_activereq,
    output logic                  s_cxs_activeack,
    output logic                  s_cxs_deacthint,

    // CXS check signals
    input  logic                  s_cxs_validchk,
    input  logic [DATACHK_W-1:0]  s_cxs_datachk,
    input  logic [CNTLCHK_W-1:0]  s_cxs_cntlchk,
    input  logic                  s_cxs_lastchk,
    input  logic                  s_cxs_prcltypechk,
    input  logic                  s_cxs_srcidchk,
    input  logic                  s_cxs_tgtidchk,
    input  logic [USERCHK_W-1:0]  s_cxs_userchk,
    output logic                  s_cxs_crdgntchk,
    input  logic                  s_cxs_crdrtnchk,
    input  logic                  s_cxs_activereqchk,
    output logic                  s_cxs_activeackchk,

    // FUB side
    output logic                  fub_cxs_valid,
    input  logic                  fub_cxs_ready,
    output logic [DW-1:0]         fub_cxs_data,
    output logic [CNTL_PW-1:0]    fub_cxs_cntl,
    output logic                  fub_cxs_last,
    output logic [2:0]            fub_cxs_prcltype,
    output logic [SRCID_PW-1:0]   fub_cxs_srcid,
    output logic [TGTID_PW-1:0]   fub_cxs_tgtid,
    output logic [USER_PW-1:0]    fub_cxs_user,

    // Status
    output logic [CRW-1:0]        credits_outstanding,
    output logic [1:0]            link_state,
    output logic                  in_packet,
    output logic                  credit_starved,
    output logic                  protocol_error,
    output logic                  parity_error,

    // Clock gating status
    output logic                  cg_gating,
    output logic                  cg_idle
);

    logic gated_aclk;
    logic int_busy;
    logic int_fub_valid;
    logic int_crdgnt;
    logic int_crdgntchk;
    logic w_req_wake;
    logic user_valid;
    logic axi_valid;

    // ACTIVEREQ wake term, synchronized on the free-running clock
    if (CXS_LINK_CTRL) begin : g_req_wake
        if (ACTIVEREQ_SYNC_STAGES >= 2) begin : g_sync
            glitch_free_n_dff_arn #(
                .FLOP_COUNT (ACTIVEREQ_SYNC_STAGES),
                .WIDTH      (1)
            ) u_req_wake_sync (
                .clk   (aclk),
                .rst_n (aresetn),
                .d     (s_cxs_activereq),
                .q     (w_req_wake)
            );
        end else begin : g_nosync
            assign w_req_wake = s_cxs_activereq;
        end
    end else begin : g_no_req_wake
        assign w_req_wake = 1'b0;
    end

    assign user_valid = int_busy;
    assign axi_valid  = s_cxs_valid || s_cxs_crdrtn || w_req_wake;

    amba_clock_gate_ctrl #(
        .CG_IDLE_COUNT_WIDTH (CG_IDLE_COUNT_WIDTH)
    ) i_amba_clock_gate_ctrl (
        .clk_in            (aclk),
        .aresetn           (aresetn),
        .cfg_cg_enable     (cfg_cg_enable),
        .cfg_cg_idle_count (cfg_cg_idle_count),
        .user_valid        (user_valid),
        .axi_valid         (axi_valid),
        .clk_out           (gated_aclk),
        .gating            (cg_gating),
        .idle              (cg_idle)
    );

    assign fub_cxs_valid   = cg_gating ? 1'b0 : int_fub_valid;
    assign s_cxs_crdgnt    = cg_gating ? 1'b0 : int_crdgnt;
    assign s_cxs_crdgntchk = (cg_gating && CXS_CHECK) ? 1'b1 : int_crdgntchk;

    cxs_slave #(
        .CXS_ISSUE             (CXS_ISSUE),
        .CXS_DATA_WIDTH        (CXS_DATA_WIDTH),
        .CXS_MAX_PKT_PER_FLIT  (CXS_MAX_PKT_PER_FLIT),
        .CXS_START_ALIGN       (CXS_START_ALIGN),
        .CXS_HAS_LAST          (CXS_HAS_LAST),
        .CXS_HAS_PRCLTYPE      (CXS_HAS_PRCLTYPE),
        .CXS_SRCID_WIDTH       (CXS_SRCID_WIDTH),
        .CXS_TGTID_WIDTH       (CXS_TGTID_WIDTH),
        .CXS_USER_WIDTH        (CXS_USER_WIDTH),
        .CXS_MAX_CREDIT        (CXS_MAX_CREDIT),
        .CXS_CREDIT_BEYOND_SPEC(CXS_CREDIT_BEYOND_SPEC),
        .CXS_STREAM_PRCL_BITS  (CXS_STREAM_PRCL_BITS),
        .CXS_STREAM_SRCID_BITS (CXS_STREAM_SRCID_BITS),
        .CXS_STREAM_TGTID_BITS (CXS_STREAM_TGTID_BITS),
        .CXS_LINK_CTRL         (CXS_LINK_CTRL),
        .CXS_CHECK             (CXS_CHECK),
        .RX_FIFO_DEPTH         (RX_FIFO_DEPTH),
        .ACTIVEREQ_SYNC_STAGES (ACTIVEREQ_SYNC_STAGES)
    ) i_cxs_slave (
        .aclk                (gated_aclk),
        .aresetn             (aresetn),
        .cfg_rx_enable       (cfg_rx_enable),
        .cfg_deact_hint      (cfg_deact_hint),
        .s_cxs_valid         (s_cxs_valid),
        .s_cxs_data          (s_cxs_data),
        .s_cxs_cntl          (s_cxs_cntl),
        .s_cxs_last          (s_cxs_last),
        .s_cxs_prcltype      (s_cxs_prcltype),
        .s_cxs_srcid         (s_cxs_srcid),
        .s_cxs_tgtid         (s_cxs_tgtid),
        .s_cxs_user          (s_cxs_user),
        .s_cxs_crdgnt        (int_crdgnt),
        .s_cxs_crdrtn        (s_cxs_crdrtn),
        .s_cxs_activereq     (s_cxs_activereq),
        .s_cxs_activeack     (s_cxs_activeack),
        .s_cxs_deacthint     (s_cxs_deacthint),
        .s_cxs_validchk      (s_cxs_validchk),
        .s_cxs_datachk       (s_cxs_datachk),
        .s_cxs_cntlchk       (s_cxs_cntlchk),
