        .DFI_DATA_WIDTH (DFI_DATA_WIDTH),
        .DFI_RATE       (DFI_RATE),
        .DFI_VALID_WIDTH(DFI_VALID_WIDTH),
        .BL_WORDS       (BL_WORDS),
